            List<String> componentClassNames = getDeclaredComponents(classLoader, COMPONENT_LIST);
            List<String> componentOverrideClassNames = getDeclaredComponents(classLoader, COMPONENT_OVERRIDE_LIST);

            // 2) For each component class name found, load its class and use introspection to find the necessary
            // annotations required to create a Component Descriptor.
            Map<RoleHint, ComponentDescriptor> descriptorMap = new HashMap<RoleHint, ComponentDescriptor>();
            for (String componentClassName : componentClassNames) {
                Class< ? > componentClass = classLoader.loadClass(componentClassName);

                // Look for ComponentRole annotations and register one component per ComponentRole found
                for (Class< ? > componentRoleClass : findComponentRoleClasses(componentClass)) {
                    for (ComponentDescriptor descriptor : factory.createComponentDescriptors(componentClass,
                        componentRoleClass)) {
                        // If there's already a existing role/hint in the list of descriptors then decide which one
                        // to keep by looking at the override list. Use those in the override list in priority.
                        // Otherwise use the last registered component.
                        RoleHint roleHint = new RoleHint(componentRoleClass, descriptor.getRoleHint());
                        if (descriptorMap.containsKey(roleHint)) {
                            // Is the component in the override list?
                            ComponentDescriptor existingDescriptor = descriptorMap.get(roleHint);
                            if (!componentOverrideClassNames.contains(existingDescriptor.getImplementation())) {
                                descriptorMap.put(new RoleHint(componentRoleClass, descriptor.getRoleHint()),
                                    descriptor);

                                if (!componentOverrideClassNames.contains(descriptor.getImplementation())) {
                                    getLogger().warn(
                                        "Component [" + existingDescriptor.getImplementation().getName()
                                            + "] is being overwritten by component ["
                                            + descriptor.getImplementation().getName()
                                            + "]. It will not be possible to look it up.");
                                }
                            }
                        } else {
                            descriptorMap.put(new RoleHint(componentRoleClass, descriptor.getRoleHint()), descriptor);
                        }
                    }
                }
            }

            // 3) Activate all component descriptors
            for (ComponentDescriptor descriptor : descriptorMap.values()) {
                manager.registerComponent(descriptor);
            }

        } catch (Exception e) {
            // Make sure we make the calling code fail in order to fail fast and prevent the application to start
            // if something is amiss.
            throw new RuntimeException("Failed to dynamically load components with annotations", e);
        }
    }

private boolean unwrap(ByteBuffer buffer) throws IOException
{
    if (_inNIOBuffer.hasContent())
        _inNIOBuffer.compact();
    else 
        _inNIOBuffer.clear();

    int total_filled=0;

    // loop filling as much encrypted data as we can into the buffer
    while (_inNIOBuffer.space()>0 && super.isOpen())
    {
        try
        {
            int filled=super.fill(_inNIOBuffer);
            if (_debug) __log.debug(_session+" unwrap filled "+filled);
            // break the loop if no progress is made (we have read everything
            // there is to read).
            if (filled<=0)
                break;
            total_filled+=filled;
        }
        catch(IOException e)
        {
            if (_inNIOBuffer.length()==0)
            {
                _outNIOBuffer.clear();
                throw e;
            }
            break;
        }
    }

    // If we have no progress and no data
    if (total_filled==0 && _inNIOBuffer.length()==0)
    {
        if(!isOpen())
        {
            _outNIOBuffer.clear();
            throw new EofException();
        }
        return false;
    }

    // We have some in data, so try to unwrap it.
    try
    {
        // inBuffer is the NIO buffer inside the _inNIOBuffer,
        // so update its position and limit from the inNIOBuffer.
        _inBuffer.position(_inNIOBuffer.getIndex());
        _inBuffer.limit(_inNIOBuffer.putIndex());
        _result=null;

        // Do the unwrap
        _result=_engine.unwrap(_inBuffer,buffer);
        if (_debug) __log.debug(_session+" unwrap unwrap "+_result);

        // skip the bytes consumed
        _inNIOBuffer.skip(_result.bytesConsumed());
    }
    finally
    {
        // reset the buffer so it can be managed by the _inNIOBuffer again.
        _inBuffer.position(0);
        _inBuffer.limit(_inBuffer.capacity());
    }

    // handle the unwrap results
    switch(_result.getStatus())
    {
        case BUFFER_OVERFLOW:
            if (buffer.position()==0) // if this buffer can't have more space
                throw new IllegalStateException(_result.toString()+" "+buffer.limit());
            // return true is some bytes somewhere were moved about.
            return total_filled>0 ||_result.bytesConsumed()>0 || _result.bytesProduced()>0;

        case BUFFER_UNDERFLOW:
            // Not enough data, 
            // If we are closed, we will never get more, so EOF
            // else return and we will be tried again
            // later when more data arriving causes another dispatch.
            if (Log.isDebugEnabled()) Log.debug("unwrap {}",_result);
            if(!isOpen())
            {
                _inNIOBuffer.clear();
                _outNIOBuffer.clear();
                throw new EofException();
            }
            return (total_filled > 0);

        case CLOSED:
            _closing=true;
            // return true is some bytes somewhere were moved about.
            return total_filled>0 ||_result.bytesConsumed()>0 || _result.bytesProduced()>0;

        case OK:
            // return true is some bytes somewhere were moved about.
            return total_filled>0 ||_result.bytesConsumed()>0 || _result.bytesProduced()>0;
        default:
            Log.warn("unwrap "+_result);
            throw new IOException(_result.toString());
    }
}

