        	}
		}
		else
		{
            if (log.isDetailed()) log.logDetailed("Table " + schemaTable + " is OK.");
		}

		if (ok_database_contype)
		{
			//
			// Populate with data...
			//
			code = DatabaseMeta.dbAccessTypeCode;
			desc = DatabaseMeta.dbAccessTypeDesc;

			if (!dryrun) {
				database.prepareInsert(table, null, tablename);
