                writer.append("javascript:confirmActionLink('");
                writer.append(confirmationMsg);
                writer.append("', '");
                WidgetWorker.buildHyperlinkUrl(writer, target, link.getUrlMode(), link.getParameterList(), link.getPrefix(context),
                        link.getFullPath(), link.getSecure(), link.getEncode(), request, response, context);
                writer.append("')");
            } else {
            WidgetWorker.buildHyperlinkUrl(writer, target, link.getUrlMode(), link.getParameterList(), link.getPrefix(context),
                    link.getFullPath(), link.getSecure(), link.getEncode(), request, response, context);
            }
        }
        writer.append("\">");
    }

    // the text
    Image img = link.getImage();
    if (img == null) {
        writer.append(link.getText(context));
    } else {
        renderImage(writer, context, img);
    }

    if (UtilValidate.isNotEmpty(target)) {
        // close tag
        writer.append("</a>");
    }

    /* NOTE DEJ20090316: This was here as a comment and not sure what it is for or if it is useful... can probably be safely removed in the future if still not used/needed
    boolean isSelected = menuItem.isSelected(context);

    String style = null;

    if (isSelected) {
    style = menuItem.getSelectedStyle();
    } else {
    style = link.getStyle(context);
    if (UtilValidate.isEmpty(style))
    style = menuItem.getTitleStyle();
    if (UtilValidate.isEmpty(style))
    style = menuItem.getWidgetStyle();
    }

    if (menuItem.getDisabled()) {
    style = menuItem.getDisabledTitleStyle();
    }

    if (UtilValidate.isNotEmpty(style)) {
    writer.append(" class=\"");
    writer.append(style);
    writer.append("\"");
    }
    */
}

public void init(ServletConfig config) throws ServletException {
    super.init(config);
    if (Debug.infoOn()) Debug.logInfo("LOADING WEBAPP [" + config.getServletContext().getContextPath().substring(1) + "] " + config.getServletContext().getServletContextName() + ", located at " + config.getServletContext().getRealPath("/"), module);

    // configure custom BSF engines
    configureBsf();
    // initialize the request handler
    getRequestHandler();
