private CoderResult decodeHasArray(ByteBuffer in, CharBuffer out) {
    int outRemaining = out.remaining();
    int pos = in.position();
    int limit = in.limit();
    final byte[] bArr = in.array();
    final char[] cArr = out.array();
    final int inIndexLimit = limit + in.arrayOffset();
    int inIndex = pos + in.arrayOffset();
    int outIndex = out.position() + out.arrayOffset();
    // if someone would change the limit in process,
    // he would face consequences
    for (; inIndex < inIndexLimit && outRemaining > 0; inIndex++) {
        int jchar = bArr[inIndex];
        if (jchar < 0) {
            jchar = jchar & 0x7F;
            int tail = remainingBytes[jchar];
            if (tail == -1) {
                in.position(inIndex - in.arrayOffset());
                out.position(outIndex - out.arrayOffset());
                return CoderResult.malformedForLength(1);
            }
            if (inIndexLimit - inIndex < 1 + tail) {
                // Apache Tomcat added tests - detect invalid sequences as
                // early as possible
                if (jchar == 0x74 && inIndexLimit > inIndex + 1) {
                    if ((bArr[inIndex + 1] & 0xFF) > 0x8F) {
                        // 11110100 1yyyxxxx xxxxxxxx xxxxxxxx
                        // Any non-zero y is > max code point
                        return CoderResult.unmappableForLength(4);
                    }
                }
                if (jchar == 0x60 && inIndexLimit > inIndex +1) {
                    if ((bArr[inIndex + 1] & 0x7F) == 0) {
                        // 11100000 10000000 10xxxxxx
                        // should have been
                        // 00xxxxxx
                        return CoderResult.malformedForLength(3);
                    }
                }
                if (jchar == 0x70 && inIndexLimit > inIndex +1) {
                    if ((bArr[inIndex + 1] & 0x7F) < 0x10) {
                        // 11110000 1000zzzz 1oyyyyyy 1oxxxxxx
                        // should have been
                        // 111ozzzz 1oyyyyyy 1oxxxxxx
                        return CoderResult.malformedForLength(4);
                    }
                }
                break;
            }
            for (int i = 0; i < tail; i++) {
                int nextByte = bArr[inIndex + i + 1] & 0xFF;
                if ((nextByte & 0xC0) != 0x80) {
                    in.position(inIndex - in.arrayOffset());
                    out.position(outIndex - out.arrayOffset());
                    return CoderResult.malformedForLength(1 + i);
                }
                jchar = (jchar << 6) + nextByte;
            }
            jchar -= remainingNumbers[tail];
            if (jchar < lowerEncodingLimit[tail]) {
                // Should have been encoded in fewer octets
                in.position(inIndex - in.arrayOffset());
                out.position(outIndex - out.arrayOffset());
                return CoderResult.malformedForLength(1);
            }
            inIndex += tail;
        }
        // Apache Tomcat added test
        if (jchar >= 0xD800 && jchar <= 0xDFFF) {
            return CoderResult.unmappableForLength(3);
        }
        // Apache Tomcat added test
        if (jchar > 0x10FFFF) {
            return CoderResult.unmappableForLength(4);
        }
        if (jchar <= 0xffff) {
            cArr[outIndex++] = (char) jchar;
            outRemaining--;
        } else {
            if (outRemaining < 2) {
                return CoderResult.OVERFLOW;
            }
            cArr[outIndex++] = (char) ((jchar >> 0xA) + 0xD7C0);
            cArr[outIndex++] = (char) ((jchar & 0x3FF) + 0xDC00);
            outRemaining -= 2;
        }
    }
    in.position(inIndex - in.arrayOffset());
    out.position(outIndex - out.arrayOffset());
    return (outRemaining == 0 && inIndex < inIndexLimit) ? CoderResult.OVERFLOW
            : CoderResult.UNDERFLOW;
}

private CoderResult decodeHasArray(ByteBuffer in, CharBuffer out) {
    int outRemaining = out.remaining();
    int pos = in.position();
    int limit = in.limit();
    final byte[] bArr = in.array();
    final char[] cArr = out.array();
    final int inIndexLimit = limit + in.arrayOffset();
    int inIndex = pos + in.arrayOffset();
    int outIndex = out.position() + out.arrayOffset();
    // if someone would change the limit in process,
    // he would face consequences
    for (; inIndex < inIndexLimit && outRemaining > 0; inIndex++) {
        int jchar = bArr[inIndex];
        if (jchar < 0) {
            jchar = jchar & 0x7F;
            int tail = remainingBytes[jchar];
            if (tail == -1) {
                in.position(inIndex - in.arrayOffset());
                out.position(outIndex - out.arrayOffset());
                return CoderResult.malformedForLength(1);
            }
            if (inIndexLimit - inIndex < 1 + tail) {
                // Apache Tomcat added test - detects invalid sequence as
                // early as possible
                if (jchar == 0x74 && inIndexLimit > inIndex + 1) {
                    if ((bArr[inIndex + 1] & 0xFF) > 0x8F) {
                        return CoderResult.unmappableForLength(4);
                    }
                }
                break;
            }
            for (int i = 0; i < tail; i++) {
                int nextByte = bArr[inIndex + i + 1] & 0xFF;
                if ((nextByte & 0xC0) != 0x80) {
                    in.position(inIndex - in.arrayOffset());
                    out.position(outIndex - out.arrayOffset());
                    return CoderResult.malformedForLength(1 + i);
                }
                jchar = (jchar << 6) + nextByte;
            }
            jchar -= remainingNumbers[tail];
            if (jchar < lowerEncodingLimit[tail]) {
                // Should have been encoded in fewer octets
                in.position(inIndex - in.arrayOffset());
                out.position(outIndex - out.arrayOffset());
                return CoderResult.malformedForLength(1);
            }
            inIndex += tail;
        }
        // Apache Tomcat added test
        if (jchar >= 0xD800 && jchar <= 0xDFFF) {
            return CoderResult.unmappableForLength(3);
        }
        // Apache Tomcat added test
        if (jchar > 0x10FFFF) {
            return CoderResult.unmappableForLength(4);
        }
        if (jchar <= 0xffff) {
            cArr[outIndex++] = (char) jchar;
            outRemaining--;
        } else {
            if (outRemaining < 2) {
                return CoderResult.OVERFLOW;
            }
            cArr[outIndex++] = (char) ((jchar >> 0xA) + 0xD7C0);
            cArr[outIndex++] = (char) ((jchar & 0x3FF) + 0xDC00);
            outRemaining -= 2;
        }
    }
    in.position(inIndex - in.arrayOffset());
    out.position(outIndex - out.arrayOffset());
    return (outRemaining == 0 && inIndex < inIndexLimit) ? CoderResult.OVERFLOW
            : CoderResult.UNDERFLOW;
}

private void checkOut(int lengthToWrite) throws IOException
{
    if (_closed)
        throw new IOException("CLOSED");

    if (_out == null)
    {            
        // If this first write is larger than buffer size, then we are committing now
        if (lengthToWrite>_wrapper.getBufferSize())
        {
            // if we know this is all the content and it is less than minimum, then do not compress, otherwise do compress
            long length=_wrapper.getContentLength();
            if (length>=0 && length<_wrapper.getMinCompressSize())
                doNotCompress(false);  // Not compressing by size, so no vary on request headers
            else
                doCompress();
        }
        else
        {
            // start aggregating writes into a buffered output stream
            _out = _bOut = new ByteArrayOutputStream2(_wrapper.getBufferSize());
        }
    }
    // else are we aggregating writes?
    else if (_bOut !=null)
    {
        // We are aggregating into the buffered output stream.  

        // If this write fills the buffer, then we are committing
        if (lengthToWrite>=(_bOut.getBuf().length - _bOut.getCount()))
        {
            // if we know this is all the content and it is less than minimum, then do not compress, otherwise do compress
            long length=_wrapper.getContentLength();
            if (length>=0 && length<_wrapper.getMinCompressSize())
                doNotCompress(false);  // Not compressing by size, so no vary on request headers
            else
                doCompress();
        }
    }
}

private void checkOut(int lengthToWrite) throws IOException
{
    if (_closed)
        throw new IOException("CLOSED");

    if (_out == null)
    {
        long length=_wrapper.getContentLength();
        if (_response.isCommitted() || (length >= 0 && length < _wrapper.getMinCompressSize()))
            doNotCompress(false);
        else if (lengthToWrite > _wrapper.getMinCompressSize())
            doCompress();
        else
            _out = _bOut = new ByteArrayOutputStream2(_wrapper.getBufferSize());
    }
    else if (_bOut != null)
    {
        long length=_wrapper.getContentLength();
        if (_response.isCommitted() || (length >= 0 && length < _wrapper.getMinCompressSize()))
            doNotCompress(false);
        else if (lengthToWrite >= (_bOut.getBuf().length - _bOut.getCount()))
            doCompress();
    }
}

protected Object get(Map<String, ? extends Object> context, TimeZone timeZone, Locale locale) {
    Object obj = null;
    try {
        obj = UelUtil.evaluate(context, new String(this.bracketedOriginal));
    } catch (PropertyNotFoundException e) {
        if (Debug.verboseOn()) {
            Debug.logVerbose("Error evaluating expression " + this + ": " + e, module);
        }
    } catch (Exception e) {
        Debug.logError("Error evaluating expression " + this + ": " + e, module);
    }
    if (obj != null) {
        try {
            // Check for runtime nesting
            String str = (String) obj;
            if (str.contains(openBracket)) {
                FlexibleStringExpander fse = FlexibleStringExpander.getInstance(str);
                if (containsScript(fse)) {
                    throw new UnsupportedOperationException("Nested scripts are not supported");
                }
                return fse.get(context, timeZone, locale);
            }
        } catch (ClassCastException e) {}
    }
    return obj;
}

private void readObject(ObjectInputStream in)
            throws IOException, ClassNotFoundException {
        // read values
        in.defaultReadObject();

        /* One expected use of serialization is to migrate HTTP sessions
         * containing a DiskFileItem between JVMs. Particularly if the JVMs are
         * on different machines It is possible that the repository location is
         * not valid so validate it.
         */
        if (repository != null) {
            if (repository.isDirectory()) {
                // Check path for nulls
                if (repository.getPath().contains("\0")) {
                    throw new IOException(format(
                            "The repository [%s] contains a null character",
                            repository.getPath()));
                }
            } else {
                throw new IOException(format(
                        "The repository [%s] is not a directory",
                        repository.getAbsolutePath()));
            }
        }

        OutputStream output = getOutputStream();
        if (cachedContent != null) {
            output.write(cachedContent);
        } else {
            FileInputStream input = new FileInputStream(dfosFile);
            IOUtils.copy(input, output);
            dfosFile.delete();
            dfosFile = null;
        }
        output.close();

        cachedContent = null;
    }

