@Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp) throws ServletException, IOException {

        resp.setContentType("application/json");
        final PrintWriter out = resp.getWriter();

        HttpSession session = req.getSession(false);

        if (session != null) {
            Subject subject = (Subject) session.getAttribute("subject");
            if (subject == null) {
                LOG.warn("No security subject stored in existing session, invalidating");
                session.invalidate();
                Helpers.doForbidden(resp);
            }
            returnPrincipals(subject, out);
            return;
        }

        AccessControlContext acc = AccessController.getContext();
        Subject subject = Subject.getSubject(acc);

        if (subject == null) {
            Helpers.doForbidden(resp);
            return;
        }
        Set<Principal> principals = subject.getPrincipals();

        String username = null;

        if (principals != null) {
            for (Principal principal : principals) {
                if (principal.getClass().getSimpleName().equals("UserPrincipal")) {
                    username = principal.getName();
                    LOG.debug("Authorizing user {}", username);
                }
            }
        }

        session = req.getSession(true);
        session.setAttribute("subject", subject);
        session.setAttribute("user", username);
        session.setAttribute("org.osgi.service.http.authentication.remote.user", username);
        session.setAttribute("org.osgi.service.http.authentication.type", HttpServletRequest.BASIC_AUTH);
        session.setAttribute("loginTime", GregorianCalendar.getInstance().getTimeInMillis());
        if (timeout != null) {
            session.setMaxInactiveInterval(timeout);
        }
        if (LOG.isDebugEnabled()) {
            LOG.debug("Http session timeout for user {} is {} sec.", username, session.getMaxInactiveInterval());
        }

        returnPrincipals(subject, out);
    }

private void gzip(ByteBuffer content, boolean complete, final Callback callback)
{
    if (content.hasRemaining() || complete)
    {
        if (content.hasArray())
            new GzipArrayCB(content,complete,callback).iterate();
        else
            new GzipBufferCB(content,complete,callback).iterate();
    }
}

private void gzip(ByteBuffer content, boolean complete, final Callback callback)
{
    if (content.hasRemaining())
    {
        if (content.hasArray())
            new GzipArrayCB(content,complete,callback).iterate();
        else
            new GzipBufferCB(content,complete,callback).iterate();
    }
    else if (complete)
    {
        _deflater.finish();

        int produced=_deflater.deflate(_buffer.array(),_buffer.arrayOffset()+_buffer.limit(),_buffer.capacity()-_buffer.limit(),Deflater.NO_FLUSH);
        _buffer.limit(_buffer.limit()+produced);
        addTrailer();
        superWrite(_buffer,complete,new Callback()
        {
            @Override
            public void succeeded()
            {
                getHttpChannel().getByteBufferPool().release(_buffer);
                _buffer=null;
                callback.succeeded();
            }

            @Override
            public void failed(Throwable x)
            {
                callback.failed(x);
            }
        });
    }
}

protected boolean isAcceptableValue(String value) {
        boolean matches = !excludedPattern.matcher(value).matches();
        if (!matches) {
            if (LOG.isTraceEnabled()) {
                LOG.trace("Cookie value [#0] matches excludedPattern [#1]", value, ExcludedPatterns.CLASS_ACCESS_PATTERN);
            }
        }
        return matches;
    }

protected boolean isExcluded(String name) {
        boolean matches = excludedPattern.matcher(name).matches();
        if (matches) {
            if (LOG.isTraceEnabled()) {
                LOG.trace("Cookie [#0] matches excludedPattern [#1]", name, ExcludedPatterns.CLASS_ACCESS_PATTERN);
            }
        } else {
            if (LOG.isTraceEnabled()) {
                LOG.trace("Cookie [#0] doesn't match excludedPattern [#1]", name, ExcludedPatterns.CLASS_ACCESS_PATTERN);
            }
        }
        return matches;
    }

public CookieInterceptor() {
        for (String pattern : ExcludedPatterns.EXCLUDED_PATTERNS) {
            excludedPatterns.add(Pattern.compile(pattern, Pattern.CASE_INSENSITIVE));
        }
    }

protected boolean isAcceptableValue(String value) {
        for (Pattern excludedPattern : excludedPatterns) {
            boolean matches = !excludedPattern.matcher(value).matches();
            if (!matches) {
                if (LOG.isTraceEnabled()) {
                    LOG.trace("Cookie value [#0] matches excludedPattern [#1]", value, excludedPattern.toString());
                }
                return false;
            }
        }
        return true;
    }

protected boolean isExcluded(String name) {
        for (Pattern excludedPattern : excludedPatterns) {
            boolean matches = excludedPattern.matcher(name).matches();
            if (matches) {
                if (LOG.isTraceEnabled()) {
                    LOG.trace("Cookie [#0] matches excludedPattern [#1]", name, excludedPattern.toString());
                }
                return true;
            } else {
                if (LOG.isTraceEnabled()) {
                    LOG.trace("Cookie [#0] doesn't match excludedPattern [#1]", name, excludedPattern.toString());
                }
            }
        }
        return false;
    }

