public InputSource resolveEntity(String publicId, String systemId) throws SAXException, IOException {
        if (systemId != null) {
            if (LOGGER.isLoggable(Level.FINE)) {
                LOGGER.fine("Will try to resolve systemId [" + systemId + "]");
            }
            // TestNG system-ids
            if (systemId.startsWith(TESTNG_NAMESPACE)) {
                LOGGER.fine("It's a TestNG document, will try to lookup DTD in classpath");
                String dtdFileName = systemId.substring(TESTNG_NAMESPACE.length());

                URL url = getClass().getClassLoader().getResource(dtdFileName);
                if (url != null)
                    return new InputSource(url.toString());
            }
        }
        // Default fallback
        return null;
    }

public JWT decode(String encodedJWT, Map<String, Verifier> verifiers, Function<Header, String> keyFunction) {
    Objects.requireNonNull(encodedJWT);
    Objects.requireNonNull(verifiers);

    String[] parts = getParts(encodedJWT);
    Header header = Mapper.deserialize(base64Decode(parts[0].getBytes(StandardCharsets.UTF_8)), Header.class);
    // Be particular about decoding an unsecured JWT. If the JWT is signed or any verifiers were provided don't do it.
    if (header.algorithm == Algorithm.none && parts.length == 2 && verifiers.isEmpty()) {
      return Mapper.deserialize(base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)), JWT.class);
    }

    // If verifiers were provided, ensure it is able to verify this JWT.
    String key = keyFunction.apply(header);
    Verifier verifier = verifiers.get(key);
    if (verifier != null) {
      if (!verifier.canVerify(header.algorithm)) {
        verifier = null;
      }
    }

    return decode(encodedJWT, header, parts, verifier);
  }

private Ccm parseCCMXmlFile(InputStream ccmXmlFile) throws IOException, SAXException {
		SecureDigester digester = new SecureDigester(CcmParser.class);

		String rootXPath = "ccm";
		digester.addObjectCreate(rootXPath, Ccm.class);
		digester.addSetProperties(rootXPath);

		String fileMetric = "ccm/metric";
		digester.addObjectCreate(fileMetric, Metric.class);
		digester.addSetProperties(fileMetric);
		digester.addBeanPropertySetter("ccm/metric/complexity");
		digester.addBeanPropertySetter("ccm/metric/unit");
		digester.addBeanPropertySetter("ccm/metric/classification");
		digester.addBeanPropertySetter("ccm/metric/file");
		digester.addBeanPropertySetter("ccm/metric/startLineNumber");
		digester.addBeanPropertySetter("ccm/metric/endLineNumber");
		digester.addSetNext(fileMetric, "addMetric", Metric.class.getName());

		return (Ccm)digester.parse(ccmXmlFile);
	}

private JWT decode(String encodedJWT, Header header, String[] parts, Verifier verifier) {
    int index = encodedJWT.lastIndexOf(".");
    // The message comprises the first two segments of the entire JWT, the signature is the last segment.
    byte[] message = encodedJWT.substring(0, index).getBytes(StandardCharsets.UTF_8);

    // If a signature is provided and verifier must be provided.
    if (parts.length == 3 && verifier == null) {
      throw new MissingVerifierException("No Verifier has been provided for verify a signature signed using [" + header.algorithm.getName() + "]");
    }

    // A verifier was provided but no signature exists, this is treated as an invalid signature.
    if (parts.length == 2 && verifier != null) {
      throw new InvalidJWTSignatureException();
    }

    if (parts.length == 3) {
      // Verify the signature before de-serializing the payload.
      byte[] signature = base64Decode(parts[2].getBytes(StandardCharsets.UTF_8));
      verifier.verify(header.algorithm, message, signature);
    }

    JWT jwt = Mapper.deserialize(base64Decode(parts[1].getBytes(StandardCharsets.UTF_8)), JWT.class);

    // Verify expiration claim
    if (jwt.isExpired()) {
      throw new JWTExpiredException();
    }

    // Verify the notBefore claim
    if (jwt.isUnavailableForProcessing()) {
      throw new JWTUnavailableForProcessingException();
    }

    return jwt;
  }

SVG  parse(InputStream is, boolean enableInternalEntities) throws SVGParseException
   {
      // Transparently handle zipped files (.svgz)
      if (!is.markSupported()) {
         // We need a a buffered stream so we can use mark() and reset()
         is = new BufferedInputStream(is);
      }
      try
      {
         is.mark(3);
         int  firstTwoBytes = is.read() + (is.read() << 8);
         is.reset();
         if (firstTwoBytes == GZIPInputStream.GZIP_MAGIC) {
            // Looks like a zipped file.
            is = new GZIPInputStream(is);
         }
      }
      catch (IOException ioe)
      {
         // Not a zipped SVG. Fall through and try parsing it normally.
      }

      try
      {
         if (enableInternalEntities)
         {
            // Use the SAXParser, which supports entities, but is slower and
            // is vulnerable to the "Billion laughs" entity expansion problem.
            parseUsingSAX(is);
         }
         else
         {
            // Use XmlPullParser, which is faster, but doesn't support entity expansion.
            parseUsingXmlPullParser(is);
         }

      }
      catch (XmlPullParserException e)
      {
         throw new SVGParseException("XML parser problem", e);
      }
      catch (IOException e)
      {
         throw new SVGParseException("Stream error", e);
      }
      // Thrown by SAX parser
      catch (ParserConfigurationException e)
      {
         throw new SVGParseException("XML parser problem", e);
      }
      catch (SAXException e)
      {
         throw new SVGParseException("SVG parse error: "+e.getMessage(), e);
      }
      finally
      {
         try {
            is.close();
         } catch (IOException e) {
            Log.e(TAG, "Exception thrown closing input stream");
         }
      }
      return svgDocument;
   }

private void parseUsingSAX(InputStream is) throws IOException, ParserConfigurationException, SAXException, SAXNotRecognizedException, SAXNotSupportedException
   {
      // Invoke the SAX XML parser on the input.
      SAXParserFactory  spf = SAXParserFactory.newInstance();

      // Disable external entity resolving
      spf.setFeature("http://xml.org/sax/features/external-general-entities", false);
      spf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

      SAXParser sp = spf.newSAXParser();
      XMLReader xr = sp.getXMLReader();

      SAXHandler  handler = new SAXHandler();
      xr.setContentHandler(handler);
      xr.setProperty("http://xml.org/sax/properties/lexical-handler", handler);

      xr.parse(new InputSource(is));
   }

private void parseUsingXmlPullParser(InputStream is) throws XmlPullParserException, IOException, SVGParseException
   {
      XmlPullParser         parser = Xml.newPullParser();
      XPPAttributesWrapper  attributes = new XPPAttributesWrapper(parser);

      parser.setFeature(XmlPullParser.FEATURE_PROCESS_DOCDECL, false);
      parser.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES, true);
      parser.setInput(is, null);

      int  eventType = parser.getEventType();
      while (eventType != XmlPullParser.END_DOCUMENT)
      {
         switch(eventType) {
            case XmlPullParser.START_DOCUMENT:
               startDocument();
               break;
            case XmlPullParser.START_TAG:
               String qName = parser.getName();
               if (parser.getPrefix() != null)
                  qName = parser.getPrefix() + ':' + qName;
               startElement(parser.getNamespace(), parser.getName(), qName, attributes);
               break;
            case XmlPullParser.END_TAG:
               qName = parser.getName();
               if (parser.getPrefix() != null)
                  qName = parser.getPrefix() + ':' + qName;
               endElement(parser.getNamespace(), parser.getName(), qName);
               break;
            case XmlPullParser.TEXT:
               int[] startAndLength = new int[2];
               char[] text = parser.getTextCharacters(startAndLength);
               text(text, startAndLength[0], startAndLength[1]);
               break;
            //case XmlPullParser.COMMENT:
            //   text(parser.getText());
            //   break;
         }
         eventType = parser.next();
      }
      endDocument();
   }

SVG  parse(InputStream is, boolean enableInternalEntities) throws SVGParseException
   {
      // Transparently handle zipped files (.svgz)
      if (!is.markSupported()) {
         // We need a a buffered stream so we can use mark() and reset()
         is = new BufferedInputStream(is);
      }
      try
      {
         is.mark(3);
         int  firstTwoBytes = is.read() + (is.read() << 8);
         is.reset();
         if (firstTwoBytes == GZIPInputStream.GZIP_MAGIC) {
            // Looks like a zipped file.
            is = new BufferedInputStream( new GZIPInputStream(is) );
         }
      }
      catch (IOException ioe)
      {
         // Not a zipped SVG. Fall through and try parsing it normally.
      }

      try
      {
         // Mark the start in case we need to restart the parsing due to switching XML parser
         // 4096 chars is hopefully enough to capture most doctype declarations that have entities.
         is.mark(ENTITY_WATCH_BUFFER_SIZE);

         // Use XmlPullParser by default, which is faster, but doesn't support entity expansion.
         // In this parser we watch for capture doctype declarations, and then switch to the SAX
         // parser if any entities are defined in the doctype.
         parseUsingXmlPullParser(is, enableInternalEntities);
      }
      finally
      {
         try {
            is.close();
         } catch (IOException e) {
            Log.e(TAG, "Exception thrown closing input stream");
         }
      }
      return svgDocument;
   }

private void parseUsingSAX(InputStream is) throws SVGParseException
   {
      try
      {
         // Invoke the SAX XML parser on the input.
         SAXParserFactory  spf = SAXParserFactory.newInstance();

         // Disable external entity resolving
         spf.setFeature("http://xml.org/sax/features/external-general-entities", false);
         spf.setFeature("http://xml.org/sax/features/external-parameter-entities", false);

         SAXParser sp = spf.newSAXParser();
         XMLReader xr = sp.getXMLReader();

         SAXHandler  handler = new SAXHandler();
         xr.setContentHandler(handler);
         xr.setProperty("http://xml.org/sax/properties/lexical-handler", handler);

         xr.parse(new InputSource(is));
      }
      catch (ParserConfigurationException e)
      {
         throw new SVGParseException("XML parser problem", e);
      }
      catch (SAXException e)
      {
         throw new SVGParseException("SVG parse error", e);
      }
      catch (IOException e)
      {
         throw new SVGParseException("Stream error", e);
      }
   }

private void parseUsingXmlPullParser(InputStream is, boolean enableInternalEntities) throws SVGParseException
   {
      try
      {
         XmlPullParser         parser = Xml.newPullParser();
         XPPAttributesWrapper  attributes = new XPPAttributesWrapper(parser);


         parser.setFeature(XmlPullParser.FEATURE_PROCESS_DOCDECL, false);
         parser.setFeature(XmlPullParser.FEATURE_PROCESS_NAMESPACES, true);
         parser.setInput(is, null);

         int  eventType = parser.getEventType();
         while (eventType != XmlPullParser.END_DOCUMENT)
         {
            switch(eventType) {
               case XmlPullParser.START_DOCUMENT:
                  startDocument();
                  break;
               case XmlPullParser.START_TAG:
                  String qName = parser.getName();
                  if (parser.getPrefix() != null)
                     qName = parser.getPrefix() + ':' + qName;
                  startElement(parser.getNamespace(), parser.getName(), qName, attributes);
                  break;
               case XmlPullParser.END_TAG:
                  qName = parser.getName();
                  if (parser.getPrefix() != null)
                     qName = parser.getPrefix() + ':' + qName;
                  endElement(parser.getNamespace(), parser.getName(), qName);
                  break;
               case XmlPullParser.TEXT:
                  int[] startAndLength = new int[2];
                  char[] text = parser.getTextCharacters(startAndLength);
                  text(text, startAndLength[0], startAndLength[1]);
                  break;
               //case XmlPullParser.COMMENT:
               //   text(parser.getText());
               //   break;

               case XmlPullParser.DOCDECL:
                  if (enableInternalEntities &&                  // entities are enabled
                      svgDocument.getRootElement() == null &&    // and we haven't already parsed the root element
                      parser.getText().contains("<!ENTITY ")) {  // and doctype seems to contain an entity definition
                     // File uses internal entities. Switch to the SAX parser.
                     try {
                        Log.d(TAG,"Switching to SAX parser to process entities");
                        is.reset();
                        parseUsingSAX(is);
                     } catch (IOException e) {
                        // reset() failed
                        Log.w(TAG, "Detected internal entity definitions, but could not parse them.");
                        // All we can do is just continue using the XmlPullParser.
                        // Entities will not be parsed properly :(
                     }
                     return;
                  }
            }
            eventType = parser.nextToken();
         }
         endDocument();

      }
      catch (XmlPullParserException e)
      {
         throw new SVGParseException("XML parser problem", e);
      }
      catch (IOException e)
      {
         throw new SVGParseException("Stream error", e);
      }
   }

@Override
    public void authorizeRequest(Operation op) {

        String suffix = UriUtils.buildUriPath(UriUtils.URI_PATH_CHAR, UriUtils.getLastPathSegment(op.getUri()));

        // allow access to ui endpoint
        if (ServiceHost.SERVICE_URI_SUFFIX_UI.equals(suffix)) {
            op.complete();
            return;
        }

        ServiceDocument doc = new ServiceDocument();
        if (this.parent.getOptions().contains(ServiceOption.FACTORY_ITEM)) {
            doc.documentSelfLink = UriUtils.buildUriPath(UriUtils.getParentPath(this.parent.getSelfLink()), suffix);
        } else {
            doc.documentSelfLink = UriUtils.buildUriPath(this.parent.getSelfLink(), suffix);
        }

        doc.documentKind = Utils.buildKind(this.parent.getStateType());
        if (getHost().isAuthorized(this.parent, doc, op)) {
            op.complete();
            return;
        }

        op.fail(Operation.STATUS_CODE_FORBIDDEN);
    }

