private static Transformer createTransformer(InputStream templateStream) throws IOException {
        try {
            // Ensure XSLT cannot use advanced extensions during processing.
            TRANSFORMER_FACTORY.setFeature(XMLConstants.FEATURE_SECURE_PROCESSING, true);
            return TRANSFORMER_FACTORY.newTransformer(new StreamSource(templateStream));
        } catch (TransformerConfigurationException e) {
            throw new ProcessingFailedException("Failed to create XSLT template", e);
        } finally {
            templateStream.close();
        }
    }

@Override
    public void call(final SourceUnit source, GeneratorContext context, ClassNode classNode) {
        if (classNode == null) { // TODO is this even possible? CpsTransformer implies it is not.
            return;
        }

        ClassCodeExpressionTransformer visitor = createVisitor(source, classNode);

        processConstructors(visitor, classNode);
        for (MethodNode m : classNode.getMethods()) {
            forbidIfFinalizer(m);
            visitor.visitMethod(m);
        }
        for (Statement s : classNode.getObjectInitializerStatements()) {
            s.visit(visitor);
        }
        for (FieldNode f : classNode.getFields()) {
            visitor.visitField(f);
        }
    }

public void forbidIfFinalizer(MethodNode m) {
        if (m.getName().equals("finalize") && m.isVoidMethod() && !m.isPrivate() && !m.isStatic()) {
            boolean safe = false;
            // There must be at least one parameter without an initial expression for the method to be acceptable.
            for (Parameter p : m.getParameters()) {
                if (!p.hasInitialExpression()) {
                    safe = true;
                    break;
                }
            }
            if (!safe) {
                throw new SecurityException("Sandboxed code may not override Object.finalize()");
            }
        }
    }

void addPathParam(String name, String value, boolean encoded) {
    if (relativeUrl == null) {
      // The relative URL is cleared when the first query parameter is set.
      throw new AssertionError();
    }
    String replacement = canonicalizeForPath(value, encoded);
    String newRelativeUrl = relativeUrl.replace("{" + name + "}", replacement);
    if (PATH_TRAVERSAL.matcher(newRelativeUrl).matches()) {
      throw new IllegalArgumentException(
          "@Path parameters shouldn't perform path traversal ('.' or '..'): " + value);
    }
    relativeUrl = newRelativeUrl;
  }

void addPathParam(String name, String value, boolean encoded) {
    if (relativeUrl == null) {
      // The relative URL is cleared when the first query parameter is set.
      throw new AssertionError();
    }
    relativeUrl = relativeUrl.replace("{" + name + "}", canonicalizeForPath(value, encoded));
  }

private Stream<MapResult> xmlXpathToMapResult(@Name("url") String url, boolean simpleMode, String path, Map<String, Object> config) throws Exception {
        if (config == null) config = Collections.emptyMap();
        boolean failOnError = (boolean) config.getOrDefault("failOnError", true);
        List<MapResult> result = new ArrayList<>();
        try {
            DocumentBuilderFactory documentBuilderFactory = DocumentBuilderFactory.newInstance();
            documentBuilderFactory.setNamespaceAware(true);
            documentBuilderFactory.setIgnoringElementContentWhitespace(true);
            documentBuilderFactory.setFeature("http://apache.org/xml/features/disallow-doctype-decl", true);
            DocumentBuilder documentBuilder = documentBuilderFactory.newDocumentBuilder();

            FileUtils.checkReadAllowed(url);

            Map<String, Object> headers = (Map) config.getOrDefault( "headers", Collections.emptyMap() );

            Document doc = documentBuilder.parse(Util.openInputStream(url, headers, null));
            XPathFactory xPathFactory = XPathFactory.newInstance();

            XPath xPath = xPathFactory.newXPath();

            path = StringUtils.isEmpty(path) ? "/" : path;
            XPathExpression xPathExpression = xPath.compile(path);
            NodeList nodeList = (NodeList) xPathExpression.evaluate(doc, XPathConstants.NODESET);

            for (int i = 0; i < nodeList.getLength(); i++) {
                final Deque<Map<String, Object>> stack = new LinkedList<>();

                handleNode(stack, nodeList.item(i), simpleMode);
                for (int index = 0; index < stack.size(); index++) {
                    result.add(new MapResult(stack.pollFirst()));
                }
            }
        }
        catch (FileNotFoundException e){
            if(!failOnError)
                return Stream.of(new MapResult(Collections.emptyMap()));
            else
                throw new FileNotFoundException(e.getMessage());
        }
        catch (Exception e){
            if(!failOnError)
                return Stream.of(new MapResult(Collections.emptyMap()));
            else
                throw new Exception(e);
        }
        return result.stream();
    }

public void toScientificString(StringBuilder result) {
    assert(!isApproximate);
    if (isNegative()) {
        result.append('-');
    }
    if (precision == 0) {
        result.append("0E+0");
        return;
    }
    // NOTE: It is not safe to add to lOptPos (aka maxInt) or subtract from
    // rOptPos (aka -maxFrac) due to overflow.
    int upperPos = Math.min(precision + scale, lOptPos) - scale - 1;
    int lowerPos = Math.max(scale, rOptPos) - scale;
    int p = upperPos;
    result.append((char) ('0' + getDigitPos(p)));
    if ((--p) >= lowerPos) {
        result.append('.');
        for (; p >= lowerPos; p--) {
            result.append((char) ('0' + getDigitPos(p)));
        }
    }
    result.append('E');
    int _scale = upperPos + scale;
    if (_scale < 0) {
        _scale *= -1;
        result.append('-');
    } else {
        result.append('+');
    }
    if (_scale == 0) {
        result.append('0');
    }
    int insertIndex = result.length();
    while (_scale > 0) {
        int quot = _scale / 10;
        int rem = _scale % 10;
        result.insert(insertIndex, (char) ('0' + rem));
        _scale = quot;
    }
}

public void toScientificString(StringBuilder result) {
    assert(!isApproximate);
    if (isNegative()) {
        result.append('-');
    }
    if (precision == 0) {
        result.append("0E+0");
        return;
    }
    // NOTE: It is not safe to add to lOptPos (aka maxInt) or subtract from
    // rOptPos (aka -maxFrac) due to overflow.
    int upperPos = Math.min(precision + scale, lOptPos) - scale - 1;
    int lowerPos = Math.max(scale, rOptPos) - scale;
    int p = upperPos;
    result.append((char) ('0' + getDigitPos(p)));
    if ((--p) >= lowerPos) {
        result.append('.');
        for (; p >= lowerPos; p--) {
            result.append((char) ('0' + getDigitPos(p)));
        }
    }
    result.append('E');
    int _scale = upperPos + scale;
    if (_scale == Integer.MIN_VALUE) {
        result.append("-2147483648");
        return;
    } else if (_scale < 0) {
        _scale *= -1;
        result.append('-');
    } else {
        result.append('+');
    }
    if (_scale == 0) {
        result.append('0');
    }
    int insertIndex = result.length();
    while (_scale > 0) {
        int quot = _scale / 10;
        int rem = _scale % 10;
        result.insert(insertIndex, (char) ('0' + rem));
        _scale = quot;
    }
}

@RequestMapping("common/download")
    public void fileDownload(String fileName, Boolean delete, HttpServletResponse response) throws IOException, FileDownloadException {
        if (StringUtils.isNotBlank(fileName) && !fileName.endsWith(".xlsx"))
            throw new FileDownloadException("不支持该类型文件下载");
        String realFileName = System.currentTimeMillis() + fileName.substring(fileName.indexOf('_') + 1);
        String filePath = "file/" + fileName;
        File file = new File(filePath);
        if (!file.exists())
            throw new FileDownloadException("文件未找到");
        response.setHeader("Content-Disposition", "attachment;fileName=" + java.net.URLEncoder.encode(realFileName, "utf-8"));
        response.setContentType("multipart/form-data");
        response.setCharacterEncoding("utf-8");
        try (InputStream inputStream = new FileInputStream(file); OutputStream os = response.getOutputStream()) {
            byte[] b = new byte[2048];
            int length;
            while ((length = inputStream.read(b)) > 0) {
                os.write(b, 0, length);
            }
        } catch (Exception e) {
            log.error("文件下载失败", e);
        } finally {
            if (delete)
                Files.delete(Paths.get(filePath));
        }
    }

