  /**
   * Parses a single field into MergeTarget. The target can be Message.Builder, FieldSet or
   * MutableMessage.
   *
   * <p>Package-private because it is used by GeneratedMessage.ExtendableMessage.
   *
   * @param tag The tag, which should have already been read.
   * @param unknownFields If not null, unknown fields will be merged to this {@link
   *     UnknownFieldSet}, otherwise unknown fields will be discarded.
   * @return {@code true} unless the tag is an end-group tag.
   */
  static boolean mergeFieldFrom(
      CodedInputStream input,
      UnknownFieldSet.Builder unknownFields,
      ExtensionRegistryLite extensionRegistry,
      Descriptors.Descriptor type,
      MergeTarget target,
      int tag)
      throws IOException {
    if (type.getOptions().getMessageSetWireFormat() && tag == WireFormat.MESSAGE_SET_ITEM_TAG) {
      mergeMessageSetExtensionFromCodedStream(
          input, unknownFields, extensionRegistry, type, target);
      return true;
    }

    final int wireType = WireFormat.getTagWireType(tag);
    final int fieldNumber = WireFormat.getTagFieldNumber(tag);

    final Descriptors.FieldDescriptor field;
    Message defaultInstance = null;

    if (type.isExtensionNumber(fieldNumber)) {
      // extensionRegistry may be either ExtensionRegistry or
      // ExtensionRegistryLite.  Since the type we are parsing is a full
      // message, only a full ExtensionRegistry could possibly contain
      // extensions of it.  Otherwise we will treat the registry as if it
      // were empty.
      if (extensionRegistry instanceof ExtensionRegistry) {
        final ExtensionRegistry.ExtensionInfo extension =
            target.findExtensionByNumber((ExtensionRegistry) extensionRegistry, type, fieldNumber);
        if (extension == null) {
          field = null;
        } else {
          field = extension.descriptor;
          defaultInstance = extension.defaultInstance;
          if (defaultInstance == null
              && field.getJavaType() == Descriptors.FieldDescriptor.JavaType.MESSAGE) {
            throw new IllegalStateException(
                "Message-typed extension lacked default instance: " + field.getFullName());
          }
        }
      } else {
        field = null;
      }
    } else if (target.getContainerType() == MergeTarget.ContainerType.MESSAGE) {
      field = type.findFieldByNumber(fieldNumber);
    } else {
      field = null;
    }

    boolean unknown = false;
    boolean packed = false;
    if (field == null) {
      unknown = true; // Unknown field.
    } else if (wireType
        == FieldSet.getWireFormatForFieldType(field.getLiteType(), /* isPacked= */ false)) {
      packed = false;
    } else if (field.isPackable()
        && wireType
            == FieldSet.getWireFormatForFieldType(field.getLiteType(), /* isPacked= */ true)) {
      packed = true;
    } else {
      unknown = true; // Unknown wire type.
    }

    if (unknown) { // Unknown field or wrong wire type.  Skip.
      if (unknownFields != null) {
        return unknownFields.mergeFieldFrom(tag, input);
      } else {
        return input.skipField(tag);
      }
    }

    if (packed) {
      final int length = input.readRawVarint32();
      final int limit = input.pushLimit(length);
      if (field.getLiteType() == WireFormat.FieldType.ENUM) {
        while (input.getBytesUntilLimit() > 0) {
          final int rawValue = input.readEnum();
          if (field.getFile().supportsUnknownEnumValue()) {
            target.addRepeatedField(
                field, field.getEnumType().findValueByNumberCreatingIfUnknown(rawValue));
          } else {
            final Object value = field.getEnumType().findValueByNumber(rawValue);
            // If the number isn't recognized as a valid value for this enum,
            // add it to the unknown fields.
            if (value == null) {
              if (unknownFields != null) {
                unknownFields.mergeVarintField(fieldNumber, rawValue);
              }
            } else {
              target.addRepeatedField(field, value);
            }
          }
        }
      } else {
        while (input.getBytesUntilLimit() > 0) {
          final Object value =
              WireFormat.readPrimitiveField(
                  input, field.getLiteType(), target.getUtf8Validation(field));
          target.addRepeatedField(field, value);
        }
      }
      input.popLimit(limit);
    } else {
      final Object value;
      switch (field.getType()) {
        case GROUP:
          {
            target.mergeGroup(input, extensionRegistry, field, defaultInstance);
            return true;
          }
        case MESSAGE:
          {
            target.mergeMessage(input, extensionRegistry, field, defaultInstance);
            return true;
          }
        case ENUM:
          final int rawValue = input.readEnum();
          if (field.getFile().supportsUnknownEnumValue()) {
            value = field.getEnumType().findValueByNumberCreatingIfUnknown(rawValue);
          } else {
            value = field.getEnumType().findValueByNumber(rawValue);
            // If the number isn't recognized as a valid value for this enum,
            // add it to the unknown fields.
            if (value == null) {
              if (unknownFields != null) {
                unknownFields.mergeVarintField(fieldNumber, rawValue);
              }
              return true;
            }
          }
          break;
        default:
          value =
              WireFormat.readPrimitiveField(
                  input, field.getLiteType(), target.getUtf8Validation(field));
          break;
      }

      if (field.isRepeated()) {
        target.addRepeatedField(field, value);
      } else {
        target.setField(field, value);
      }
    }

    return true;
  }

  /** Read a message from the given input stream into the provided target and UnknownFieldSet. */
  static void mergeMessageFrom(
      Message.Builder target,
      UnknownFieldSet.Builder unknownFields,
      CodedInputStream input,
      ExtensionRegistryLite extensionRegistry)
      throws IOException {
    BuilderAdapter builderAdapter = new BuilderAdapter(target);
    Descriptor descriptorForType = target.getDescriptorForType();
    while (true) {
      final int tag = input.readTag();
      if (tag == 0) {
        break;
      }

      if (!mergeFieldFrom(
          input, unknownFields, extensionRegistry, descriptorForType, builderAdapter, tag)) {
        // end group tag
        break;
      }
    }
  }

  /** Called by {@code #mergeFieldFrom()} to parse a MessageSet extension into MergeTarget. */
  private static void mergeMessageSetExtensionFromCodedStream(
      CodedInputStream input,
      UnknownFieldSet.Builder unknownFields,
      ExtensionRegistryLite extensionRegistry,
      Descriptors.Descriptor type,
      MergeTarget target)
      throws IOException {

    // The wire format for MessageSet is:
    //   message MessageSet {
    //     repeated group Item = 1 {
    //       required uint32 typeId = 2;
    //       required bytes message = 3;
    //     }
    //   }
    // "typeId" is the extension's field number.  The extension can only be
    // a message type, where "message" contains the encoded bytes of that
    // message.
    //
    // In practice, we will probably never see a MessageSet item in which
    // the message appears before the type ID, or where either field does not
    // appear exactly once.  However, in theory such cases are valid, so we
    // should be prepared to accept them.

    int typeId = 0;
    ByteString rawBytes = null; // If we encounter "message" before "typeId"
    ExtensionRegistry.ExtensionInfo extension = null;

    // Read bytes from input, if we get it's type first then parse it eagerly,
    // otherwise we store the raw bytes in a local variable.
    while (true) {
      final int tag = input.readTag();
      if (tag == 0) {
        break;
      }

      if (tag == WireFormat.MESSAGE_SET_TYPE_ID_TAG) {
        typeId = input.readUInt32();
        if (typeId != 0) {
          // extensionRegistry may be either ExtensionRegistry or
          // ExtensionRegistryLite. Since the type we are parsing is a full
          // message, only a full ExtensionRegistry could possibly contain
          // extensions of it. Otherwise we will treat the registry as if it
          // were empty.
          if (extensionRegistry instanceof ExtensionRegistry) {
            extension =
                target.findExtensionByNumber((ExtensionRegistry) extensionRegistry, type, typeId);
          }
        }

      } else if (tag == WireFormat.MESSAGE_SET_MESSAGE_TAG) {
        if (typeId != 0) {
          if (extension != null && ExtensionRegistryLite.isEagerlyParseMessageSets()) {
            // We already know the type, so we can parse directly from the
            // input with no copying.  Hooray!
            eagerlyMergeMessageSetExtension(input, extension, extensionRegistry, target);
            rawBytes = null;
            continue;
          }
        }
        // We haven't seen a type ID yet or we want parse message lazily.
        rawBytes = input.readBytes();

      } else { // Unknown tag. Skip it.
        if (!input.skipField(tag)) {
          break; // End of group
        }
      }
    }
    input.checkLastTagWas(WireFormat.MESSAGE_SET_ITEM_END_TAG);

    // Process the raw bytes.
    if (rawBytes != null && typeId != 0) { // Zero is not a valid type ID.
      if (extension != null) { // We known the type
        mergeMessageSetExtensionFromBytes(rawBytes, extension, extensionRegistry, target);
      } else { // We don't know how to parse this. Ignore it.
        if (rawBytes != null && unknownFields != null) {
          unknownFields.mergeField(
              typeId, UnknownFieldSet.Field.newBuilder().addLengthDelimited(rawBytes).build());
        }
      }
    }
  }

  private static void mergeMessageSetExtensionFromBytes(
      ByteString rawBytes,
      ExtensionRegistry.ExtensionInfo extension,
      ExtensionRegistryLite extensionRegistry,
      MergeTarget target)
      throws IOException {

    Descriptors.FieldDescriptor field = extension.descriptor;
    boolean hasOriginalValue = target.hasField(field);

    if (hasOriginalValue || ExtensionRegistryLite.isEagerlyParseMessageSets()) {
      // If the field already exists, we just parse the field.
      Object value =
          target.parseMessageFromBytes(
              rawBytes, extensionRegistry, field, extension.defaultInstance);
      target.setField(field, value);
    } else {
      // Use LazyField to load MessageSet lazily.
      LazyField lazyField = new LazyField(extension.defaultInstance, extensionRegistry, rawBytes);
      target.setField(field, lazyField);
    }
  }

  private static void eagerlyMergeMessageSetExtension(
      CodedInputStream input,
      ExtensionRegistry.ExtensionInfo extension,
      ExtensionRegistryLite extensionRegistry,
      MergeTarget target)
      throws IOException {
    Descriptors.FieldDescriptor field = extension.descriptor;
    Object value = target.parseMessage(input, extensionRegistry, field, extension.defaultInstance);
    target.setField(field, value);
  }
}

public Object query(String query) throws ApplicationException {
    StringBuffer html = new StringBuffer();
    String[] keywords;

    int page = 1, pageSize = 20;

    this.request = (Request) this.context
            .getAttribute(HTTP_REQUEST);
    if (this.request.getParameter("page") == null
            || this.request.getParameter("page").toString().trim().length() <= 0) {
        page = 1;
    } else {
        page = Integer.parseInt(this.request.getParameter("page").toString());
    }

    int startIndex = (page - 1) * pageSize;
    this.setVariable("search.title", "无相关结果 - ");

    if (query.trim().length() > 0) {
        query = StringUtilities.htmlSpecialChars(query);
        if (query.indexOf('|') != -1) {
            String[] q = query.split("|");
            query = q[0];
        }

        query = query.trim();
        keywords = query.split(" ");

        this.setVariable("keyword", query);
        this.setVariable("search.title", query + " - ");
    } else {
        this.setVariable("keyword", "");
        return this;
    }

    StringBuffer condition = new StringBuffer();
    int i = 0, j, k = 0;
    String _keyword;
    while (i < keywords.length) {
        _keyword = keywords[i];
        if (_keyword.trim().length() > 0) {
            if (condition.length() == 0) {
                condition.append(" bible.content like '%" + _keyword + "%' ");
            } else {
                condition.append(" AND bible.content like '%" + _keyword + "%' ");
                /*
                 * if(true)
                 * condition.append(" AND bible.content like '%"+keywords[i]+"%' ");
                 * else
                 * condition.append(" OR bible.content like '%"+keywords[i]+"%' ");
                 */
            }
        }
        i++;
    }

    Locale locale = this.getLocale();
    if (condition.length() == 0)
        condition.append(" book.language='" + locale + "' ");
    else
        condition.append(" AND book.language='" + locale + "' ");

    book book = new book();
    bible bible = new bible();
    if (locale.toString().equalsIgnoreCase(Locale.US.toString())) {
        bible.setTableName("NIV");
    } else if (locale.toString().equalsIgnoreCase(Locale.UK.toString())) {
        bible.setTableName("ESV");
    } else {
        bible.setTableName(locale.toString());
    }

    String SQL = "SELECT bible.*,book.book_name FROM " + bible.getTableName()
            + " as bible left join " + book.getTableName()
            + " as book on bible.book_id=book.book_id where " + condition
            + " order by bible.book_id,bible.chapter_id limit " + startIndex + ","
            + pageSize;
    String look = "SELECT count(bible.id) AS size FROM " + bible.getTableName()
            + " as bible left join " + book.getTableName()
            + " as book on bible.book_id=book.book_id where " + condition;

    Table vtable = bible.find(SQL, new Object[]{});
    boolean noResult = vtable.size() > 0;

    if (!noResult && query.length() > 0) {
        try {
            Table list = book.findWith("WHERE language=? and book_name=?",
                    new Object[]{this.getLocale().toString(), query});
            if (list.size() > 0) {
                this.response = (Response) this.context
                        .getAttribute(HTTP_RESPONSE);

                Reforward reforward = new Reforward(request, response);
                query = URLEncoder.encode(query, "utf-8");
                reforward.setDefault(this.context.getAttribute("HTTP_HOST") + query);
                reforward.forward();
                return reforward;
            }
        } catch (ApplicationException e) {
            // TODO Auto-generated catch block
            e.printStackTrace();
        } catch (UnsupportedEncodingException e) {
            // TODO Auto-generated catch block
            e.printStackTrace();
        }
    }

    Row found = bible.findOne(look, new Object[]{});

    long startTime = System.currentTimeMillis();
    Pager pager = new Pager();
    pager.setPageSize(pageSize);
    pager.setCurrentPage(page);
    pager.setListSize(found.getFieldInfo("size").intValue());

    Field field;
    int next = pager.getStartIndex();// 此位置即为当前页的第一条记录的ID

    html.append("<ol class=\"searchresults\" start=\"" + next + "\">\r\n");

    String finded, word;
    Row row;
    Enumeration<Row> table = vtable.elements();
    int n = 0;
    while (table.hasMoreElements()) {
        row = table.nextElement();
        Iterator<Field> iterator = row.iterator();

        n++;
        while (iterator.hasNext()) {
            field = iterator.next();
            finded = field.get("content").value().toString();

            j = 0;
            while (j < keywords.length) {
                finded = StringUtilities.sign(finded, keywords[j++]);
            }

            html.append("<li"
                    + (n % 2 == 0 ? " class=\"even\"" : " class=\"odd\"")
                    + "><a href=\""
                    + this.context.getAttribute("HTTP_HOST")
                    + "bible/"
                    + field.get("book_id").value().toString()
                    + "/"
                    + field.get("chapter_id").value().toString()
                    + "/"
                    + field.get("part_id").value().toString()
                    + "\" target=\"_blank\">"
                    + this.setText("search.bible.info", field.get("book_name").value()
                    .toString(), field.get("chapter_id").value().toString(), field
                    .get("part_id").value().toString()) + "</a><p>" + finded
                    + "</p></li> \r\n");
            next++;
        }
    }

    Table ktable;
    Row krow;
    while (k < keywords.length && noResult) {
        word = keywords[k++];
        keyword keyword = new keyword();
        keyword.setKeyword(word);
        ktable = keyword.setRequestFields("id,visit").findWith("WHERE keyword=?",
                new Object[]{word});

        if (ktable.size() == 0) {
            keyword.setVisit(0);
            keyword.append();
        } else {
            krow = ktable.get(0);
            keyword.setId(krow.getFieldInfo("id").value());
            keyword.setVisit(krow.getFieldInfo("visit").intValue() + 1);
            keyword.update();
        }
    }
    html.append("</ol>\r\n");

    String actionURL = this.context.getAttribute("HTTP_HOST") + "bible/search/"
            + query + "&page";
    pager.setFirstPageText(this.getProperty("page.first.text"));
    pager.setLastPageText(this.getProperty("page.last.text"));
    pager.setCurrentPageText(this.getProperty("page.current.text"));
    pager.setNextPageText(this.getProperty("page.next.text"));
    pager.setEndPageText(this.getProperty("page.end.text"));
    pager.setControlBarText(this.getProperty("page.controlbar.text"));

    html.append("<div class=\"pagination\" style=\"cursor:default\">"
            + pager.getPageControlBar(actionURL) + "</div>\r\n");
    html.append("<!-- "
            + String.valueOf(System.currentTimeMillis() - startTime) + " -->");

    int start = page - 1 == 0 ? 1 : (page - 1) * pageSize + 1, end = page
            * pageSize;

    this.setVariable("start", String.valueOf(start));
    this.setVariable("end", String.valueOf(end));
    this.setVariable("size", String.valueOf(pager.getSize()));
    this.setVariable("value", html.toString());
    this.setVariable("action", this.config.get("default.base_url")
            + this.context.getAttribute("REQUEST_ACTION").toString());

    this.setText("search.info", start, end, query, pager.getSize());

    Session session = request.getSession();
    if (session.getAttribute("usr") != null) {
        this.usr = (User) session.getAttribute("usr");

        this.setVariable("user.status", "");
        this.setVariable("user.profile",
                "<a href=\"javascript:void(0)\" onmousedown=\"profileMenu.show(event,'1')\">"
                        + this.usr.getEmail() + "</a>");
    } else {
        this.setVariable("user.status", "<a href=\"" + this.getLink("user/login")
                + "\">" + this.getProperty("page.login.caption") + "</a>");
        this.setVariable("user.profile", "");
    }

    return this;
}

