                                return null;
                            }, template.getContent().getAuthorReference(),
                                template.getContent().getDocumentReference());
                        } catch (Exception e) {
                            this.logger.error("Failed to evaluate macros templates [{}]", template.getPath(), e);
                        }
                    }
                }
            }
        }

        return velocityEngine;
