                .append(zoom)
                .append("\" lat=\"")
                .append(latitude)
                .append("\" ")
                .append("lon=\"")
                .append(longitude)
                .append("\" controls controlslist=\"geolocation\">\n")
                .append("<layer- label=\"")
                .append(escapeHtml4(layerLabel))
                .append("\" ")
                .append("src=\"")
                .append(request.getContextPath())
                .append(request.getServletPath())
                .append("/")
                .append(escapeHtml4(layer))
                .append("/")
                .append(proj)
