                .append(!styleName.isEmpty() ? "?style=" + escapeHtml4(styleName) : "")
                .append("\" checked></layer->\n")
                .append("</mapml-viewer>\n")
                .append("</body>\n")
                .append("</html>");
        return sb.toString();
    }

